import sys, re, os
def render(tpl, cmd, hook, echo, resolve):
    env = {'cmd': cmd is not None, 'echo': echo, 'resolve': resolve,
           'hook_none': hook == 'none', 'hook_prompt': hook == 'prompt', 'hook_pwd': hook == 'pwd'}
    def ev(cond):
        cond = cond.strip()
        for part in cond.split('||'):
            part = part.strip()
            ok = True
            for a in part.split('&&'):
                a = a.strip()
                neg = a.startswith('!')
                if neg: a = a[1:].strip()
                v = env[a]
                if neg: v = not v
                ok = ok and v
            if ok: return True
        return False
    out = []
    stack = []  # each: [active_parent, taken, cur_active]
    active = True
    lines = tpl.split('\n')
    for line in lines:
        s = line.strip()
        m = re.fullmatch(r'\{%\s*(if|elif|else|endif)\s*(.*?)\s*%\}', s)
        if m:
            kw, cond = m.group(1), m.group(2)
            if kw == 'if':
                stack.append([active, False, False])
                parent = active
                c = parent and ev(cond)
                stack[-1][1] = c; stack[-1][2] = c
                active = c
            elif kw == 'elif':
                parent, taken, _ = stack[-1]
                c = parent and not taken and ev(cond)
                if c: stack[-1][1] = True
                active = c
            elif kw == 'else':
                parent, taken, _ = stack[-1]
                c = parent and not taken
                stack[-1][1] = True
                active = c
            else:
                parent = stack.pop()[0]
                active = parent
            continue
        if active:
            out.append(line.replace('{{cmd}}', cmd if cmd is not None else ''))
    return '\n'.join(out)

shell = sys.argv[1]
tpl = open(f'/tmp/tpl/{shell}.txt').read()
bad = 0
for c in ['z', 'j', 'cd', 'NONE']:
    for h in ['none', 'prompt', 'pwd']:
        for e in [0, 1]:
            for r in [0, 1]:
                exp = open(f'/tmp/allinit/{shell}.{c}.{h}.e{e}.r{r}.txt').read()
                got = render(tpl, None if c == 'NONE' else c, h, bool(e), bool(r))
                if got != exp:
                    bad += 1
                    if bad <= int(os.environ.get('SHOW', '1')):
                        print(f'MISMATCH {shell} {c} {h} e{e} r{r}')
                        open('/tmp/tpl/got.txt','w').write(got)
                        os.system(f'diff /tmp/tpl/got.txt /tmp/allinit/{shell}.{c}.{h}.e{e}.r{r}.txt | head -40')
print(shell, 'bad', bad)
EOF
echo ok"}

