import difflib, sys, itertools
MARK = 'QQCMDQQ'
def load(shell, c, h, e, r):
    t = open(f'/tmp/allinit2/{shell}.{c}.{h}.e{e}.r{r}.txt').read()
    return t.replace(MARK, '{{cmd}}')

# item: ('line', text) or ('if', cond, then_items, else_items)
def key(it):
    return repr(it)

def merge(cond, A, B):
    # A, B: lists of items
    if A == B: return A
    ka = [key(x) for x in A]; kb = [key(x) for x in B]
    sm = difflib.SequenceMatcher(None, ka, kb, autojunk=False)
    out = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'equal':
            out.extend(A[i1:i2])
        else:
            out.append(('if', cond, A[i1:i2], B[j1:j2]))
    return out

def build(shell, varsleft, assign):
    if not varsleft:
        c = 'QQCMDQQ' if assign['cmd'] else 'NONE'
        h = assign['hook']
        txt = load(shell, c, h, int(assign['echo']), int(assign['resolve']))
        return [('line', l) for l in txt.split('\n')]
    v = varsleft[0]; rest = varsleft[1:]
    if v == 'hook':
        P = build(shell, rest, {**assign, 'hook': 'pwd'})
        Q = build(shell, rest, {**assign, 'hook': 'prompt'})
        N = build(shell, rest, {**assign, 'hook': 'none'})
        QN = merge('hook_prompt', Q, N)
        return merge('hook_pwd', P, QN)
    A = build(shell, rest, {**assign, v: True})
    B = build(shell, rest, {**assign, v: False})
    return merge(v, A, B)

def emit(items, out):
    for it in items:
        if it[0] == 'line':
            out.append(it[1])
        else:
            _, cond, a, b = it
            if not a:
                out.append('{%% if !%s %%}' % cond)
                emit(b, out)
                out.append('{% endif %}')
            else:
                out.append('{%% if %s %%}' % cond)
                emit(a, out)
                if b:
                    out.append('{% else %}')
                    emit(b, out)
                out.append('{% endif %}')

shell = sys.argv[1]
order = sys.argv[2].split(',') if len(sys.argv) > 2 else ['cmd', 'hook', 'echo', 'resolve']
items = build(shell, order, {})
out = []
emit(items, out)
open(f'/tmp/tpl/{shell}.txt', 'w').write('\n'.join(out))
print(shell, len(out), 'lines')
