//! Command-line interface definition.

use std::ffi::OsString;
use std::path::PathBuf;

use clap::builder::PossibleValuesParser;
use clap::{value_parser, Arg, ArgAction, ArgMatches, Command};

const BOLD_UL: &str = "\x1b[1m\x1b[4m";
const END_BOLD_UL: &str = "\x1b[22m\x1b[24m";
const BOLD: &str = "\x1b[1m";
const END_BOLD: &str = "\x1b[22m";

const ENV_VARS: &[(&str, &str)] = &[
    ("_ZO_DATA_DIR", "Path for zoxide data files"),
    ("_ZO_ECHO", "Print the matched directory before navigating to it when set to 1"),
    ("_ZO_EXCLUDE_DIRS", "List of directory globs to be excluded"),
    ("_ZO_FZF_OPTS", "Custom flags to pass to fzf"),
    ("_ZO_MAXAGE", "Maximum total age after which entries start getting deleted"),
    ("_ZO_RESOLVE_SYMLINKS", "Resolve symlinks when storing paths"),
];

fn help_template() -> String {
    let width = ENV_VARS.iter().map(|(name, _)| name.len()).max().unwrap_or(0);
    let mut tpl = String::new();
    tpl.push_str("{before-help}");
    tpl.push_str(BOLD_UL);
    tpl.push_str("{name} {version}");
    tpl.push_str(END_BOLD_UL);
    tpl.push_str("\n{author}\nhttps://github.com/ajeetdsouza/zoxide\n\n{about}\n\n");
    tpl.push_str("{usage-heading}\n{tab}{usage}\n\n{all-args}{after-help}\n\n");
    tpl.push_str(BOLD_UL);
    tpl.push_str("Environment variables:");
    tpl.push_str(END_BOLD_UL);
    for (name, desc) in ENV_VARS {
        tpl.push_str("\n{tab}");
        tpl.push_str(BOLD);
        tpl.push_str(name);
        tpl.push_str(END_BOLD);
        for _ in name.len()..width + 2 {
            tpl.push(' ');
        }
        tpl.push_str(desc);
    }
    tpl
}

fn with_template(cmd: Command, tpl: &str) -> Command {
    cmd.help_template(tpl.to_string())
}

fn edit_path_cmd(name: &'static str) -> Command {
    Command::new(name).arg(Arg::new("path").value_name("PATH").required(true).action(ArgAction::Set))
}

pub fn build() -> Command {
    let tpl = help_template();

    let add = with_template(Command::new("add"), &tpl)
        .about("Add a new directory or increment its rank")
        .arg(
            Arg::new("paths")
                .value_name("PATHS")
                .required(true)
                .num_args(1..)
                .action(ArgAction::Append)
                .value_parser(value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("score")
                .short('s')
                .long("score")
                .value_name("SCORE")
                .action(ArgAction::Set)
                .value_parser(value_parser!(f64))
                .help("The rank to increment the entry if it exists or initialize it with if it doesn't"),
        );

    let edit = with_template(Command::new("edit"), &tpl)
        .about("Edit the database")
        .subcommand(edit_path_cmd("decrement").hide(true))
        .subcommand(edit_path_cmd("delete").hide(true))
        .subcommand(edit_path_cmd("increment").hide(true))
        .subcommand(Command::new("reload").hide(true));

    let import = with_template(Command::new("import"), &tpl)
        .about("Import entries from another application")
        .arg(
            Arg::new("path")
                .value_name("PATH")
                .required(true)
                .action(ArgAction::Set)
                .value_parser(value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("from")
                .long("from")
                .value_name("FROM")
                .required(true)
                .action(ArgAction::Set)
                .value_parser(PossibleValuesParser::new(["autojump", "z"]))
                .help("Application to import from"),
        )
        .arg(
            Arg::new("merge")
                .long("merge")
                .action(ArgAction::SetTrue)
                .help("Merge into existing database"),
        );

    let init = with_template(Command::new("init"), &tpl)
        .about("Generate shell configuration")
        .arg(
            Arg::new("shell")
                .value_name("SHELL")
                .required(true)
                .action(ArgAction::Set)
                .value_parser(PossibleValuesParser::new([
                    "bash",
                    "elvish",
                    "fish",
                    "nushell",
                    "posix",
                    "powershell",
                    "tcsh",
                    "xonsh",
                    "zsh",
                ])),
        )
        .arg(
            Arg::new("no-cmd")
                .long("no-cmd")
                .action(ArgAction::SetTrue)
                .help("Prevents zoxide from defining the `z` and `zi` commands"),
        )
        .arg(
            Arg::new("cmd")
                .long("cmd")
                .value_name("CMD")
                .action(ArgAction::Set)
                .default_value("z")
                .help("Changes the prefix of the `z` and `zi` commands"),
        )
        .arg(
            Arg::new("hook")
                .long("hook")
                .value_name("HOOK")
                .action(ArgAction::Set)
                .default_value("pwd")
                .value_parser(PossibleValuesParser::new(["none", "prompt", "pwd"]))
                .help("Changes how often zoxide increments a directory's score"),
        );

    let query = with_template(Command::new("query"), &tpl)
        .about("Search for a directory in the database")
        .arg(Arg::new("keywords").value_name("KEYWORDS").num_args(0..).action(ArgAction::Append))
        .arg(
            Arg::new("all")
                .short('a')
                .long("all")
                .action(ArgAction::SetTrue)
                .help("Show unavailable directories"),
        )
        .arg(
            Arg::new("interactive")
                .short('i')
                .long("interactive")
                .action(ArgAction::SetTrue)
                .conflicts_with("list")
                .help("Use interactive selection"),
        )
        .arg(
            Arg::new("list")
                .short('l')
                .long("list")
                .action(ArgAction::SetTrue)
                .conflicts_with("interactive")
                .help("List all matching directories"),
        )
        .arg(
            Arg::new("score")
                .short('s')
                .long("score")
                .action(ArgAction::SetTrue)
                .help("Print score with results"),
        )
        .arg(
            Arg::new("exclude")
                .long("exclude")
                .value_name("path")
                .action(ArgAction::Set)
                .help("Exclude the current directory"),
        )
        .arg(
            Arg::new("base-dir")
                .long("base-dir")
                .value_name("path")
                .action(ArgAction::Set)
                .help("Only search within this directory"),
        );

    let remove = with_template(Command::new("remove"), &tpl)
        .about("Remove a directory from the database")
        .arg(Arg::new("paths").value_name("PATHS").num_args(0..).action(ArgAction::Append));

    Command::new("zoxide")
        .version(env!("CARGO_PKG_VERSION"))
        .author("Ajeet D'Souza <98ajeet@gmail.com>")
        .about("A smarter cd command for your terminal")
        .help_template(tpl.clone())
        .disable_help_subcommand(true)
        .propagate_version(true)
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(add)
        .subcommand(edit)
        .subcommand(import)
        .subcommand(init)
        .subcommand(query)
        .subcommand(remove)
}

/// The parsed command line.
pub enum Cmd {
    Add { paths: Vec<PathBuf>, score: Option<f64> },
    Edit(Option<EditCmd>),
    Import { path: PathBuf, from: String, merge: bool },
