            score: m.get_one::<f64>("score").copied(),
        },
        Some(("edit", m)) => Cmd::Edit(match m.subcommand() {
            Some(("decrement", s)) => Some(EditCmd::Decrement(string(s, "path").unwrap_or_default())),
            Some(("delete", s)) => Some(EditCmd::Delete(string(s, "path").unwrap_or_default())),
            Some(("increment", s)) => Some(EditCmd::Increment(string(s, "path").unwrap_or_default())),
            Some(("reload", _)) => Some(EditCmd::Reload),
            _ => None,
        }),
        Some(("import", m)) => Cmd::Import {
            path: m.get_one::<PathBuf>("path").cloned().unwrap_or_default(),
            from: string(m, "from").unwrap_or_default(),
            merge: m.get_flag("merge"),
        },
        Some(("init", m)) => Cmd::Init {
            shell: string(m, "shell").unwrap_or_default(),
            cmd: if m.get_flag("no-cmd") { None } else { Some(string(m, "cmd").unwrap_or_default()) },
            hook: string(m, "hook").unwrap_or_default(),
        },
        Some(("query", m)) => Cmd::Query(QueryArgs {
            keywords: strings(m, "keywords"),
            all: m.get_flag("all"),
            interactive: m.get_flag("interactive"),
            list: m.get_flag("list"),
            score: m.get_flag("score"),
            exclude: string(m, "exclude"),
            base_dir: string(m, "base-dir"),
        }),
        Some(("remove", m)) => Cmd::Remove { paths: strings(m, "paths") },
        _ => unreachable!("subcommand is required"),
    }
}
