//! Error helpers.

use std::fmt::{self, Display, Formatter, Write as _};
use std::io;

use anyhow::{bail, Context, Result};

/// An error that causes the process to exit with the given code without
/// printing anything.
#[derive(Debug)]
pub struct SilentExit {
    pub code: u8,
}

impl Display for SilentExit {
    fn fmt(&self, _: &mut Formatter<'_>) -> fmt::Result {
        Ok(())
    }
}

impl std::error::Error for SilentExit {}

/// Converts broken pipe errors into a silent exit, and annotates all other
/// write errors with the device that was being written to.
pub trait BrokenPipeHandler {
    fn pipe_exit(self, device: &str) -> Result<()>;
}

impl BrokenPipeHandler for io::Result<()> {
    fn pipe_exit(self, device: &str) -> Result<()> {
        match self {
            Err(e) if e.kind() == io::ErrorKind::BrokenPipe => bail!(SilentExit { code: 0 }),
            result => result.with_context(|| format!("could not write to {device}")),
        }
    }
}

/// Formats an error and its chain of causes.
pub fn format_error(err: &anyhow::Error) -> String {
    let mut out = String::new();
    let mut chain = err.chain();
    if let Some(top) = chain.next() {
        let _ = write!(out, "{top}");
    }
    let causes: Vec<String> = chain.map(|c| c.to_string()).collect();
    if !causes.is_empty() {
        out.push_str("\n\nCaused by:");
        let numbered = causes.len() > 1;
        for (n, cause) in causes.iter().enumerate() {
            out.push('\n');
            for (i, line) in cause.split('\n').enumerate() {
                if i == 0 {
                    if numbered {
                        let _ = write!(out, "{n: >5}: ");
                    } else {
                        out.push_str("    ");
                    }
                } else {
                    out.push('\n');
                    if numbered {
                        out.push_str("       ");
                    } else {
                        out.push_str("    ");
                    }
                }
                out.push_str(line);
            }
        }
    }
    out
}
