//! The on-disk database of directories.

use std::fmt::{self, Display, Formatter};
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};

use crate::{config, util};

pub type Rank = f64;
pub type Epoch = u64;

const HOUR: Epoch = 60 * 60;
const DAY: Epoch = 24 * HOUR;
const WEEK: Epoch = 7 * DAY;

#[derive(Clone, Debug)]
pub struct Dir {
    pub path: String,
    pub rank: Rank,
    pub last_accessed: Epoch,
}

impl Dir {
    pub fn score(&self, now: Epoch) -> Rank {
        let age = now.saturating_sub(self.last_accessed);
        if age < HOUR {
            self.rank * 4.0
        } else if age < DAY {
            self.rank * 2.0
        } else if age < WEEK {
            self.rank / 2.0
        } else {
            self.rank / 4.0
        }
    }

    pub fn display(&self) -> DirDisplay<'_> {
        DirDisplay { dir: self, now: None, separator: ' ' }
    }
}

pub struct DirDisplay<'a> {
    dir: &'a Dir,
    now: Option<Epoch>,
    separator: char,
}

impl DirDisplay<'_> {
    pub fn with_score(mut self, now: Epoch) -> Self {
        self.now = Some(now);
        self
    }

    pub fn with_separator(mut self, separator: char) -> Self {
        self.separator = separator;
        self
    }
}

impl Display for DirDisplay<'_> {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        if let Some(now) = self.now {
            let score = self.dir.score(now).clamp(0.0, 9999.0);
            write!(f, "{score:>6.1}{}", self.separator)?;
        }
        write!(f, "{}", self.dir.path)
    }
}

pub struct Database {
    path: PathBuf,
    dirs: Vec<Dir>,
    dirty: bool,
}

impl Database {
    const VERSION: u32 = 3;

    pub fn open() -> Result<Self> {
        let data_dir = config::data_dir()?;
        Self::open_dir(&data_dir)
    }

    pub fn open_dir(data_dir: &Path) -> Result<Self> {
        let path = data_dir.join("db.zo");
        match fs::read(&path) {
            Ok(bytes) => {
                let dirs = decode(&bytes)?;
                Ok(Database { path, dirs, dirty: false })
            }
            Err(e) if e.kind() == io::ErrorKind::NotFound => {
                fs::create_dir_all(data_dir).with_context(|| {
                    format!("unable to create data directory: {}", data_dir.display())
                })?;
                Ok(Database { path, dirs: Vec::new(), dirty: false })
            }
            Err(e) => {
                Err(e).with_context(|| format!("could not read from database: {}", path.display()))
            }
        }
    }

    pub fn save(&mut self) -> Result<()> {
        if !self.dirty {
            return Ok(());
        }
        let bytes = encode(&self.dirs);
        util::write(&self.path, &bytes).context("could not write to database")?;
        self.dirty = false;
        Ok(())
    }

    pub fn dirs(&self) -> &[Dir] {
        &self.dirs
    }

    pub fn dirty(&self) -> bool {
        self.dirty
    }

    /// Increments the rank of a directory, or creates it if it doesn't exist.
    /// The access time of existing entries is left untouched.
    pub fn add(&mut self, path: &str, by: Rank, now: Epoch) {
        match self.dirs.iter_mut().find(|dir| dir.path == path) {
            Some(dir) => dir.rank = (dir.rank + by).max(0.0),
            None => self.dirs.push(Dir { path: path.to_string(), rank: by.max(0.0), last_accessed: now }),
        }
        self.dirty = true;
    }

    /// Increments the rank of a directory and updates its access time, or
    /// creates it if it doesn't exist.
    pub fn add_update(&mut self, path: &str, by: Rank, now: Epoch) {
        match self.dirs.iter_mut().find(|dir| dir.path == path) {
            Some(dir) => {
                dir.rank = (dir.rank + by).max(0.0);
                dir.last_accessed = now;
            }
            None => self.dirs.push(Dir { path: path.to_string(), rank: by.max(0.0), last_accessed: now }),
        }
        self.dirty = true;
    }

    /// Appends an entry without checking for duplicates.
    pub fn add_unchecked(&mut self, path: &str, rank: Rank, last_accessed: Epoch) {
        self.dirs.push(Dir { path: path.to_string(), rank, last_accessed });
        self.dirty = true;
    }

    pub fn remove(&mut self, path: &str) -> bool {
        match self.dirs.iter().position(|dir| dir.path == path) {
            Some(idx) => {
                self.swap_remove(idx);
                true
            }
            None => false,
        }
    }

    pub fn swap_remove(&mut self, idx: usize) {
        self.dirs.swap_remove(idx);
        self.dirty = true;
    }

    /// Scales down all ranks once the total exceeds `max_age`, dropping
    /// entries whose rank falls below 1.
    pub fn age(&mut self, max_age: Rank) {
        let total: Rank = self.dirs.iter().map(|dir| dir.rank).sum();
        if total > max_age {
            let factor = 0.9 * max_age / total;
            for idx in (0..self.dirs.len()).rev() {
                let dir = &mut self.dirs[idx];
                dir.rank *= factor;
                if dir.rank < 1.0 {
                    self.dirs.swap_remove(idx);
                }
            }
            self.dirty = true;
        }
    }

    /// Merges entries with identical paths.
    pub fn dedup(&mut self) {
        self.dirs.sort_unstable_by(|a, b| a.path.cmp(&b.path));
        for idx in (1..self.dirs.len()).rev() {
            if self.dirs[idx].path != self.dirs[idx - 1].path {
                continue;
            }
            let (rank, last_accessed) = (self.dirs[idx].rank, self.dirs[idx].last_accessed);
            let prev = &mut self.dirs[idx - 1];
            prev.last_accessed = prev.last_accessed.max(last_accessed);
            prev.rank += rank;
            self.dirs.swap_remove(idx);
            self.dirty = true;
        }
    }

    pub fn sort_by_score(&mut self, now: Epoch) {
        self.dirs.sort_unstable_by(|a, b| a.score(now).total_cmp(&b.score(now)));
        self.dirty = true;
    }
}

fn encode(dirs: &[Dir]) -> Vec<u8> {
    let size = 12 + dirs.iter().map(|dir| 24 + dir.path.len()).sum::<usize>();
    let mut out = Vec::with_capacity(size);
    out.extend_from_slice(&Database::VERSION.to_le_bytes());
    out.extend_from_slice(&(dirs.len() as u64).to_le_bytes());
    for dir in dirs {
        out.extend_from_slice(&(dir.path.len() as u64).to_le_bytes());
        out.extend_from_slice(dir.path.as_bytes());
        out.extend_from_slice(&dir.rank.to_le_bytes());
        out.extend_from_slice(&dir.last_accessed.to_le_bytes());
    }
    out
}

fn decode(bytes: &[u8]) -> Result<Vec<Dir>> {
    if bytes.len() < 4 {
        bail!("could not deserialize database: corrupted data");
    }
    let (version, rest) = bytes.split_at(4);
    let version = u32::from_le_bytes(version.try_into().unwrap());
    if version != Database::VERSION {
        bail!("unsupported version (got {version}, supports {})", Database::VERSION);
    }
    decode_dirs(rest).map_err(anyhow::Error::msg).context("could not deserialize database")
}

struct Reader<'a> {
    buf: &'a [u8],
}

impl<'a> Reader<'a> {
    fn fixed<const N: usize>(&mut self) -> Result<[u8; N], String> {
        if self.buf.len() < N {
            return Err("io error: unexpected end of file".to_string());
        }
        let (head, tail) = self.buf.split_at(N);
        self.buf = tail;
        Ok(head.try_into().unwrap())
    }

    fn u64(&mut self) -> Result<u64, String> {
        self.fixed::<8>().map(u64::from_le_bytes)
    }

    fn f64(&mut self) -> Result<f64, String> {
        self.fixed::<8>().map(f64::from_le_bytes)
    }

    fn str(&mut self) -> Result<&'a str, String> {
        let len = self.u64()?;
        if len > self.buf.len() as u64 {
            return Err("io error: ".to_string());
        }
        let (head, tail) = self.buf.split_at(len as usize);
        self.buf = tail;
        std::str::from_utf8(head).map_err(|e| format!("string is not valid utf8: {e}"))
    }
}

fn decode_dirs(bytes: &[u8]) -> Result<Vec<Dir>, String> {
    let mut reader = Reader { buf: bytes };
    let len = reader.u64()?;
    let mut dirs = Vec::with_capacity(len.min(4096) as usize);
    for _ in 0..len {
        let path = reader.str()?.to_string();
        let rank = reader.f64()?;
        let last_accessed = reader.u64()?;
        dirs.push(Dir { path, rank, last_accessed });
    }
    if !reader.buf.is_empty() {
        return Err("Slice had bytes remaining after deserialization".to_string());
    }
    Ok(dirs)
}
