//! Assorted helpers: paths, time, atomic writes and fzf.

use std::env;
use std::ffi::OsStr;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::path::{Component, Path, PathBuf};
use std::process::{Child, ChildStdin, Command, Stdio};
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{bail, Context, Result};

use crate::config;
use crate::db::{Dir, Epoch};
use crate::error::SilentExit;

pub fn current_time() -> Result<Epoch> {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system clock set to invalid time")?
        .as_secs();
    Ok(now)
}

pub fn current_dir() -> Result<PathBuf> {
    env::current_dir().context("could not get current directory")
}

pub fn canonicalize<P: AsRef<Path>>(path: P) -> Result<PathBuf> {
    let path = path.as_ref();
    fs::canonicalize(path).with_context(|| format!("could not resolve path: {}", path.display()))
}

pub fn path_to_str(path: &Path) -> Result<&str> {
    path.to_str().with_context(|| format!("invalid unicode in path: {}", path.display()))
}

/// Makes a path absolute and lexically normalizes `.` and `..` components,
/// without touching the filesystem.
pub fn resolve_path<P: AsRef<Path>>(path: P) -> Result<PathBuf> {
    let path = path.as_ref();
    let mut components = path.components().peekable();
    let mut stack: Vec<Component<'_>> = Vec::new();
    let base;

    match components.peek() {
        Some(Component::RootDir) => {
            stack.push(components.next().unwrap());
        }
        _ => {
            base = current_dir()?;
            stack.extend(base.components());
        }
    }

    for component in components {
        match component {
            Component::Normal(_) => stack.push(component),
            Component::CurDir => {}
            Component::ParentDir => {
                if !matches!(stack.last(), Some(Component::RootDir) | None) {
                    stack.pop();
                }
            }
            Component::RootDir | Component::Prefix(_) => {}
        }
    }

    Ok(stack.iter().collect())
}

/// A small, non-cryptographic random number generator (wyrand).
struct Rng(u64);

impl Rng {
    fn new() -> Self {
        let nanos = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0);
        let local = 0u8;
        let addr = &local as *const u8 as u64;
        Rng(nanos ^ (u64::from(std::process::id()) << 32) ^ addr.rotate_left(17))
    }

    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0xa076_1d64_78bd_642f);
        let t = u128::from(self.0) * u128::from(self.0 ^ 0xe703_7ed1_a0b4_28db);
        (t as u64) ^ ((t >> 64) as u64)
    }

    fn alphanumeric(&mut self) -> char {
        const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        CHARS[(self.next() % CHARS.len() as u64) as usize] as char
    }
}

fn tmpfile(dir: &Path) -> Result<(File, PathBuf)> {
    const MAX_ATTEMPTS: usize = 5;
    let mut rng = Rng::new();
    let mut attempts = 0;
    loop {
        attempts += 1;
        let mut name = String::from("tmp_");
        name.extend((0..12).map(|_| rng.alphanumeric()));
        let path = dir.join(name);
        match OpenOptions::new().write(true).create_new(true).open(&path) {
            Ok(file) => return Ok((file, path)),
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists && attempts < MAX_ATTEMPTS => {}
            Err(e) => {
                return Err(e).with_context(|| format!("could not create file: {}", path.display()))
            }
        }
    }
}

/// Atomically replaces the file at `path` with `contents`.
pub fn write(path: &Path, contents: &[u8]) -> Result<()> {
    let dir = path.parent().unwrap_or_else(|| Path::new("."));
    let (mut file, tmp_path) = tmpfile(dir)?;
    let result = (|| -> Result<()> {
        file.write_all(contents)
            .with_context(|| format!("could not write to file: {}", tmp_path.display()))?;

        // Preserve the ownership of the file being replaced.
        #[cfg(unix)]
        if let Ok(metadata) = fs::metadata(path) {
            use std::os::unix::fs::MetadataExt;
            let _ = std::os::unix::fs::fchown(&file, Some(metadata.uid()), Some(metadata.gid()));
        }

        file.sync_all().with_context(|| format!("could not sync writes to file: {}", tmp_path.display()))?;
        fs::rename(&tmp_path, path).with_context(|| format!("could not replace file: {}", path.display()))
    })();
    drop(file);
    if result.is_err() {
        let _ = fs::remove_file(&tmp_path);
    }
    result
}

const PREVIEW: &str = "--preview=\\command -p ls -Cp --color=always --group-directories-first {2..}";
const PREVIEW_WINDOW: &str = "--preview-window=down,30%,sharp";

pub struct Fzf(Command);

impl Fzf {
    fn base() -> Self {
        let mut cmd = Command::new("fzf");
        cmd.args(["--delimiter=\t", "--nth=2", "--read0"]).stdin(Stdio::piped()).stdout(Stdio::piped());
        Fzf(cmd)
    }

    fn colors(mut self) -> Self {
        self.0.env("CLICOLOR", "1").env("CLICOLOR_FORCE", "1").env("SHELL", "sh");
        self
    }

    /// The fzf configuration used by `zoxide query --interactive`.
    pub fn query() -> Self {
        let mut fzf = Self::base();
        match config::fzf_opts() {
            Some(opts) => {
                fzf.0.env("FZF_DEFAULT_OPTS", opts);
                fzf
