        let Some((last, rest)) = self.options.keywords.split_last() else {
            return true;
        };

        let path = path.to_lowercase();
        let mut path = path.as_str();
        match path.rfind(last.as_str()) {
            Some(idx) => {
                if path[idx + last.len()..].contains('/') {
                    return false;
                }
                path = &path[..idx];
            }
            None => return false,
        }

        for keyword in rest.iter().rev() {
            match path.rfind(keyword.as_str()) {
                Some(idx) => path = &path[..idx],
                None => return false,
            }
        }
        true
    }

    fn filter_by_base_dir(&self, path: &str) -> bool {
        match &self.options.base_dir {
            Some(base_dir) => Path::new(path).starts_with(base_dir),
            None => true,
        }
    }

    fn filter_by_exists(&self, path: &str) -> bool {
        if !self.options.exists {
            return true;
        }
        let metadata =
            if self.options.resolve_symlinks { fs::symlink_metadata(path) } else { fs::metadata(path) };
        metadata.map(|m| m.is_dir()).unwrap_or(false)
    }
}
