        "elvish" => include_str!("../templates/elvish.txt"),
        "fish" => include_str!("../templates/fish.txt"),
        "nushell" => include_str!("../templates/nushell.txt"),
        "posix" => include_str!("../templates/posix.txt"),
        "powershell" => include_str!("../templates/powershell.txt"),
        "tcsh" => include_str!("../templates/tcsh.txt"),
        "xonsh" => include_str!("../templates/xonsh.txt"),
        "zsh" => include_str!("../templates/zsh.txt"),
        _ => return None,
    })
}

impl Opts<'_> {
    fn var(&self, name: &str) -> bool {
        match name {
            "cmd" => self.cmd.is_some(),
            "echo" => self.echo,
            "resolve" => self.resolve_symlinks,
            "hook_none" => self.hook == "none",
            "hook_prompt" => self.hook == "prompt",
            "hook_pwd" => self.hook == "pwd",
            _ => panic!("unknown template variable: {name}"),
        }
    }

    /// Evaluates a condition of the form `a && !b || c`.
    fn eval(&self, cond: &str) -> bool {
        cond.split("||").any(|conj| {
            conj.split("&&").all(|atom| {
                let atom = atom.trim();
                match atom.strip_prefix('!') {
                    Some(name) => !self.var(name.trim()),
                    None => self.var(atom),
                }
            })
        })
    }
}

enum Directive<'a> {
    If(&'a str),
    Elif(&'a str),
    Else,
    Endif,
}

fn parse_directive(line: &str) -> Option<Directive<'_>> {
    let inner = line.trim().strip_prefix("{%")?.strip_suffix("%}")?.trim();
    let (keyword, rest) = match inner.split_once(char::is_whitespace) {
        Some((keyword, rest)) => (keyword, rest.trim()),
        None => (inner, ""),
    };
    match keyword {
        "if" => Some(Directive::If(rest)),
        "elif" => Some(Directive::Elif(rest)),
        "else" => Some(Directive::Else),
        "endif" => Some(Directive::Endif),
        _ => None,
    }
}

/// Renders a template. Lines of the form `{% if cond %}`, `{% elif cond %}`,
/// `{% else %}` and `{% endif %}` control which lines are emitted, and
/// `{{cmd}}` is replaced by the command prefix.
pub fn render(template: &str, opts: &Opts<'_>) -> String {
    struct Frame {
        parent_active: bool,
        taken: bool,
    }

    let cmd = opts.cmd.unwrap_or_default();
    let mut out = String::with_capacity(template.len() + 256);
    let mut stack: Vec<Frame> = Vec::new();
    let mut active = true;
    let mut first = true;

    for line in template.split('\n') {
        if let Some(directive) = parse_directive(line) {
            match directive {
                Directive::If(cond) => {
                    let taken = active && opts.eval(cond);
                    stack.push(Frame { parent_active: active, taken });
                    active = taken;
                }
                Directive::Elif(cond) => {
                    let frame = stack.last_mut().expect("unbalanced template");
                    active = frame.parent_active && !frame.taken && opts.eval(cond);
                    frame.taken |= active;
                }
                Directive::Else => {
                    let frame = stack.last_mut().expect("unbalanced template");
                    active = frame.parent_active && !frame.taken;
                    frame.taken = true;
                }
                Directive::Endif => {
                    let frame = stack.pop().expect("unbalanced template");
                    active = frame.parent_active;
                }
            }
            continue;
        }
        if !active {
            continue;
        }
        if !first {
            out.push('\n');
        }
        first = false;
        out.push_str(&line.replace("{{cmd}}", cmd));
    }
    out
}
