use std::fs;
use std::path::Path;

use anyhow::{bail, Context, Result};

use crate::db::Database;

pub fn run(path: &Path, from: &str, merge: bool) -> Result<()> {
    let buffer = fs::read_to_string(path)
        .with_context(|| format!("could not open database for importing: {}", path.display()))?;

    let mut db = Database::open()?;
    if !merge && !db.dirs().is_empty() {
        bail!("current database is not empty, specify --merge to continue anyway");
    }

    match from {
        "autojump" => from_autojump(&mut db, &buffer),
        _ => from_z(&mut db, &buffer),
    }
    .context("import error")?;

    db.save()
}

fn from_autojump(db: &mut Database, buffer: &str) -> Result<()> {
    for line in buffer.lines() {
        if line.is_empty() {
            continue;
        }
        let (rank, path) = line.split_once('\t').with_context(|| format!("invalid entry: {line}"))?;
        let rank = rank.parse::<f64>().with_context(|| format!("invalid rank: {rank}"))?;
        // Normalize the rank using a sigmoid function.
        let rank = 1.0 / (1.0 + (-rank).exp());
        db.add_unchecked(path, rank, 0);
    }
    if db.dirty() {
        db.dedup();
    }
    Ok(())
}

fn from_z(db: &mut Database, buffer: &str) -> Result<()> {
    for line in buffer.lines() {
        if line.is_empty() {
            continue;
        }
        let mut fields = line.rsplitn(3, '|');

        let last_accessed = fields.next().with_context(|| format!("invalid entry: {line}"))?;
        let last_accessed =
            last_accessed.parse::<u64>().with_context(|| format!("invalid epoch: {last_accessed}"))?;

        let rank = fields.next().with_context(|| format!("invalid entry: {line}"))?;
        let rank = rank.parse::<f64>().with_context(|| format!("invalid rank: {rank}"))?;

        let path = fields.next().with_context(|| format!("invalid entry: {line}"))?;
        db.add_unchecked(path, rank, last_accessed);
    }
    if db.dirty() {
        db.dedup();
    }
    Ok(())
}
